    address: string;
    port?: number;
    credentialId: string;
    scannerId?: string;
    sudo?: boolean;
    hostKeyFingerprint?: string;
    /**
     * Host public key to pin, in `known_hosts` / `authorized_keys` form: `<type> <base64>` (for example `ssh-ed25519 AAAA…`).
     */
    hostKey?: string;
    /**
     * Minutes between scheduled scans. 0 means on demand only.
     */
