export type TlsEndpointName = 'web' | 'agent';

/**
 * `auto`: issued and renewed by an internal CA. `manual`: chain and key
 * supplied by the administrator. `off` (reported for `web` only, never
 * accepted in an update): the server does not terminate Web/API TLS
 * because `BOMCENSUS_WEB_TLS=off`; subject, issuer and names are empty
 * and `expiresAt` is absent.
 *
 */
export type TlsCertMode = 'auto' | 'manual' | 'off';

export type TlsEndpoint = {
    mode: TlsCertMode;
    subject: string;
    issuer: string;
    /**
     * Subject alternative names.
     */
    names: Array<string>;
    expiresAt?: string;
    /**
     * `agent` only: subject of the client certificate the server presents to listen-mode agents, when it is not the server certificate.
     */
    clientSubject?: string;
    /**
     * `agent` only: expiry of that client certificate.
     */
    clientExpiresAt?: string;
};

export type PendingAnchor = {
    /**
     * Unpadded base64url SHA-256 of the new anchor's SPKI.
     */
    spkiHash: string;
    subject: string;
    expiresAt: string;
    preparedAt: string;
    /**
     * Non-revoked agents that have not picked up the bundle containing this anchor.
     */
    unsyncedAgents: number;
};

export type TlsState = {
    web: TlsEndpoint;
    agent: TlsEndpoint;
    /**
     * Unpadded base64url SHA-256 of the Agent TLS trust anchor's SPKI (the `ca-hash` of enrollment strings).
     */
    anchorSpkiHash: string;
    /**
     * Expiry of the Agent CA that issues agent certificates.
     */
    agentCaExpiresAt: string;
    /**
     * Non-revoked agents that do not hold the current trust bundle.
     */
    unsyncedAgents: number;
    pendingAnchor?: PendingAnchor;
};

export type TlsEndpointUpdate = {
    mode: TlsCertMode;
    /**
     * PEM certificates, leaf first. Required for `manual`.
     */
    certificateChain?: string;
    /**
     * `agent` with `manual` only: PEM certificates, leaf first, of the
     * client-authentication certificate the server presents to
     * listen-mode agents. It must chain to the same trust anchor as
     * `certificateChain`. When absent, the `certificateChain` leaf is
     * used and must allow both server and client authentication.
     *
     */
    clientCertificateChain?: string;
};

export type AgentAnchorChange = {
    action: 'prepare' | 'activate' | 'cancel';
    /**
     * `prepare` in manual mode: PEM certificate of the new anchor.
     */
    certificate?: string;
    /**
     * `activate` even though some agents have not synchronized.
     */
    force?: boolean;
};

export type FeedInstance = {
    /**
     * Public key, `x25519 <base64>`.
     */
    instanceId: string;
    createdAt: string;
};

/**
 * `never`: not contacted yet (or a new key was just trusted).
 * `connected`: the last contact succeeded. `key_changed`: the server
 * presented another key than the stored one and is not used.
 * `error`: the last contact failed (`lastError`).
 *
 */
export type FeedServerStatus = 'never' | 'connected' | 'key_changed' | 'error';

export type FeedSource = {
    name: string;
    /**
     * Last successful collection.
     */
    updatedAt?: string;
    /**
     * Last collection that changed data.
     */
    changedAt?: string;
    /**
     * False when the last collection failed.
     */
    healthy?: boolean;
};

export type FeedServer = {
    id: string;
    name: string;
    url: string;
    /**
     * The default server; it cannot be removed.
     */
    builtin: boolean;
    /**
     * Components are matched against this server.
     */
    active: boolean;
    enabled: boolean;
    /**
     * Allow the server to count this installation's queries in its anonymous daily statistics.
     */
    telemetry: boolean;
    /**
     * Trusted server key, absent before the first contact.
     */
    serverKey?: string;
    keyTrustedAt?: string;
    /**
     * Key the server presented in the `key_changed` state.
     */
    presentedKey?: string;
    presentedAt?: string;
    status: FeedServerStatus;
    lastError?: string;
    lastErrorAt?: string;
    lastOkAt?: string;
    /**
     * The server's grade of this instance, e.g. `anonymous`.
     */
    grade?: string;
    sessionExpiresAt?: string;
    /**
     * Data revision at the last status check.
     */
    revision?: number;
    /**
     * Matching rules digest at the last status check.
     */
    rulesDigest?: string;
    sources: Array<FeedSource>;
    statusCheckedAt?: string;
    matching?: FeedMatchCounts;
    createdAt: string;
};

/**
 * Active server only, after the first status check: live components by
 * match state against the current data revision and rules.
 *
 */
export type FeedMatchCounts = {
    checked: number;
    /**
     * The feed server has no data for these; they are not known to be safe.
     */
    unsupported: number;
    invalid: number;
    pending: number;
    /**
     * Checked components with at least one vulnerability.
     */
    vulnerable: number;
};

export type FeedServerList = {
    items: Array<FeedServer>;
    total: number;
};

export type FeedServerCreate = {
    name: string;
    url: string;
    telemetry?: boolean;
};

export type FeedServerUpdate = {
    name?: string;
    enabled?: boolean;
    telemetry?: boolean;
    /**
     * Only `true` is accepted; activating another server deactivates this one.
     */
    active?: boolean;
};

export type FeedServerTrustKey = {
    /**
     * The presented key, `x25519 <base64>`.
     */
    key: string;
};

/**
 * Rating of a match: the distribution's rating of a package match when
 * its advisories have one (Debian urgency), otherwise the CVSS rating
 * of the highest base score. `negligible` comes from distributions
 * only (Debian `unimportant`: the binary packages are not affected,
 * or it is not a security problem there). On a vulnerability or an
 * aggregate, the highest rating of its matches.
 *
 */
export type Severity = 'critical' | 'high' | 'medium' | 'low' | 'negligible' | 'none';

export type FixState = 'fixed' | 'not_fixed' | 'will_not_fix' | 'under_investigation' | 'unknown';

export type VulnAdvisory = {
    source: string;
    id: string;
    /**
     * The distribution's rating, when it has one.
     */
    severity?: string;
};

export type ComponentMatchState = {
    status: 'checked' | 'unsupported' | 'invalid';
    reason?: string;
    /**
     * The release OS packages were matched against.
     */
    osKey?: string;
    revision: number;
    matchedAt: string;
};

export type ComponentVulnerability = {
    vulnId: string;
    aliases: Array<string>;
    summary?: string;
    severity?: Severity;
    /**
     * Highest CVSS base score.
     */
    score?: number;
    /**
     * Listed in the CISA Known Exploited Vulnerabilities catalog.
     */
    kev: boolean;
    kevAdded?: string;
    epss?: number;
    epssPercentile?: number;
    published?: string;
    /**
     * `package`: an advisory of the package's ecosystem. `cpe`: a CPE configuration (NVD, VulnCheck or the CNA).
     */
    method: 'package' | 'cpe';
    ecosystem?: string;
    fixState: FixState;
    fixedVersion?: string;
    cpeMatch?: 'exact' | 'range';
    rangeSource?: 'nvd' | 'vulncheck' | 'cna';
    /**
     * The match holds only together with one of these CPEs, which were not checked.
     */
    platforms: Array<string>;
    advisories: Array<VulnAdvisory>;
};

export type ComponentVulnerabilities = {
    match?: ComponentMatchState;
    items: Array<ComponentVulnerability>;
};

/**
 * `listening`: a process that loaded the component listens on a
 * non-loopback address. `running`: a process loaded it.
 * `installed`: no process did. `unknown`: the processes were not fully
 * collected.
 *
 */
export type Exposure = 'listening' | 'running' | 'installed' | 'unknown';

/**
 * `host` for the asset itself, `runtime` for files added in the running container, `image` for the image content.
 */
export type FindingLayer = 'host' | 'runtime' | 'image';

/**
 * Locations (asset and container) by exposure.
 */
export type ExposureCounts = {
    listening: number;
    running: number;
    installed: number;
    unknown: number;
};

/**
 * Vulnerabilities by rating; `unknown` have no rating.
 */
export type SeverityCounts = {
    critical: number;
    high: number;
    medium: number;
    low: number;
    negligible: number;
    unknown: number;
};

export type ProcessCount = {
    exe: string;
    count: number;
};

export type FindingProcess = {
    pid: number;
    exe: string;
    pod?: string;
    /**
     * Non-loopback listening sockets, `tcp/443`.
     */
    ports: Array<string>;
};

/**
 * An update action. `fixedVersion` is the version that fixes all its vulnerabilities, when one is known.
 */
export type VulnComponent = {
    componentId: string;
    name: string;
    version: string;
    type: ComponentType;
    purl?: string;
    fixedVersion?: string;
    /**
     * Distinct fixed versions of its vulnerabilities.
     */
    fixedVersions: Array<string>;
    /**
     * Vulnerabilities without a fixed version.
     */
    unfixed?: number;
    cves: number;
    kev: number;
    severityCounts: SeverityCounts;
    score?: number;
    severity?: Severity;
    epss?: number;
    exposure: Exposure;
    exposureCounts: ExposureCounts;
    assets: number;
    /**
     * Executables of the loading processes, most frequent first (at most 5).
     */
    processes: Array<ProcessCount>;
    /**
     * Deferred findings among them (when deferred ones are included).
     */
    deferred?: number;
};

export type VulnComponentList = {
    items: Array<VulnComponent>;
    total: number;
};

export type VulnCve = {
    vulnId: string;
    summary?: string;
    severity?: Severity;
    score?: number;
    kev: boolean;
    kevAdded?: string;
    epss?: number;
    epssPercentile?: number;
    components: number;
    assets: number;
    exposure: Exposure;
    exposureCounts: ExposureCounts;
    /**
     * In the context of one component.
     */
    fixState?: FixState;
    /**
     * In the context of one component.
     */
    fixedVersion?: string;
    /**
     * In the context of one component; the loading processes of the most exposed location.
     */
    processes?: Array<FindingProcess>;
    /**
     * In the context of one component: present when the Go executables at one location link a vulnerable function, absent when those at every location link none. Absent when not known.
     */
    reachability?: Reachability;
    /**
     * In the context of one component; the vulnerable functions checked against the Go executables (package path and name).
     */
    symbols?: Array<string>;
    /**
     * In the context of one component; locations whose Go executables link none of the vulnerable functions.
     */
    symbolAbsent?: number;
    /**
     * Deferred findings among them (when deferred ones are included).
     */
    deferred?: number;
    /**
     * In the context of one component; the triage rules deciding its findings.
     */
    rules?: Array<TriageRule>;
};

export type VulnCveList = {
    items: Array<VulnCve>;
    total: number;
};

/**
 * One place a component is, with the open findings there.
 */
export type VulnLocation = {
    assetId: string;
    assetName: string;
    assetKind: AssetKind;
    container?: string;
    layer: FindingLayer;
    imageDigest?: string;
    componentId: string;
    componentName: string;
    componentVersion: string;
    /**
     * File paths (or the package database) of the component there.
     */
    locations: Array<string>;
    method?: DetectMethod;
    exposure: Exposure;
    /**
     * From the Go executables there: present when one links a vulnerable function of one of the CVEs, absent when none links any for all of them. Absent when not known.
     */
    reachability?: Reachability;
    /**
     * CVEs there whose vulnerable functions are linked into none of the executables.
     */
    symbolAbsent?: number;
    processes: Array<FindingProcess>;
    cves: number;
    firstSeen: string;
};

/**
 * Whether the vulnerable Go functions are linked into the executables. `symbol_absent` lowers the exposure to installed.
 */
